-- 부트 것을 하나 본다

// HibernateJpaAutoConfiguration
@AutoConfiguration(after = { DataSourceAutoConfiguration.class,
                            TransactionManagerCustomizationAutoConfiguration.class })
@ConditionalOnClass({ LocalContainerEntityManagerFactoryBean.class,
                      EntityManager.class, SessionImplementor.class })
public class HibernateJpaAutoConfiguration extends JpaBaseConfiguration { ... }

$ ./gradlew bootRun --args='--debug' 2>&1 \
    | grep -E 'DataSourceAutoConfiguration matched|HibernateJpaAutoConfiguration matched'
   DataSourceAutoConfiguration matched:
   HibernateJpaAutoConfiguration matched:

$ ./gradlew bootRun 2>&1 | grep -nE 'HikariPool|HHH000412' | head -2
41:INFO ... : HikariPool-1 - Start completed.
52:INFO ... : HHH000412: Hibernate ORM core version 6.5.2.Final

--   ⑦ 1장에서 보던 그 순서다


-- 순서를 찍어 본다

package study.lib;

@AutoConfiguration
public class AlphaAutoConfiguration {
    public AlphaAutoConfiguration() { System.out.println("[구성] alpha"); }
    @Bean Greeter alphaGreeter() { System.out.println("[빈] alpha"); return n -> "A"; }
}

@AutoConfiguration
public class BetaAutoConfiguration {
    public BetaAutoConfiguration() { System.out.println("[구성] beta"); }
    @Bean Greeter betaGreeter() { System.out.println("[빈] beta"); return n -> "B"; }
}

// imports 파일
study.lib.AlphaAutoConfiguration
study.lib.BetaAutoConfiguration

$ ./gradlew bootRun 2>&1 | grep -E '\[구성\]|\[빈\]'
[구성] alpha
[빈] alpha
[구성] beta
[빈] beta

--   적은 순서대로 돌았다


-- 파일 순서를 뒤집으면

// imports 파일
study.lib.BetaAutoConfiguration
study.lib.AlphaAutoConfiguration

$ ./gradlew bootRun 2>&1 | grep '\[구성\]'
[구성] beta
[구성] alpha

--   그대로 따라간다
--   아무것도 안 적으면 이렇게 흔들린다


-- 사실은 이름으로 한 번 정렬한다

// imports 파일
study.lib.ZuluAutoConfiguration
study.lib.AlphaAutoConfiguration

$ ./gradlew bootRun 2>&1 | grep '\[구성\]'
[구성] alpha
[구성] zulu

--   적은 순서가 아니라 이름 순이 됐다
--   그래도 믿을 건 못 된다


-- 앞뒤를 지정한다

@AutoConfiguration(after = BetaAutoConfiguration.class)
public class AlphaAutoConfiguration { ... }

$ ./gradlew bootRun 2>&1 | grep '\[구성\]'
[구성] beta
[구성] alpha

// 반대로 적으면
@AutoConfiguration(before = BetaAutoConfiguration.class)
public class AlphaAutoConfiguration { ... }

$ ./gradlew bootRun 2>&1 | grep '\[구성\]'
[구성] alpha
[구성] beta

--   이름 순을 이겼다


-- 순서가 결과를 바꾼다

@AutoConfiguration
public class AlphaAutoConfiguration {
    @Bean @ConditionalOnMissingBean Greeter greeter() { return n -> "A"; }
}

@AutoConfiguration
public class BetaAutoConfiguration {
    @Bean @ConditionalOnMissingBean Greeter greeter() { return n -> "B"; }
}

$ curl -s 'localhost:8080/greet?name=철수'
A

$ ./gradlew bootRun --args='--debug' 2>&1 \
    | grep -A2 'BetaAutoConfiguration#greeter:' | tail -2
         - @ConditionalOnMissingBean found beans of type 'study.lib.Greeter' greeter

// 베타를 앞으로 보내면
@AutoConfiguration(before = AlphaAutoConfiguration.class)
public class BetaAutoConfiguration { ... }

$ curl -s 'localhost:8080/greet?name=철수'
B

--   코드는 그대로인데 답이 바뀌었다
--   6.5절의 조건이 순서에 기댄다는 뜻이다


-- 내 구성이 늘 먼저다

@Configuration
class MyGreeterConfig {
    @Bean Greeter greeter() { System.out.println("[내] greeter"); return n -> "내 것"; }
}

$ ./gradlew bootRun 2>&1 | grep -E '\[내\]|\[구성\]'
[내] greeter
[구성] alpha
[구성] beta

$ curl -s 'localhost:8080/greet?name=철수'
내 것

--   before 를 뭘로 적든 내 것이 먼저다
--   6.5절이 늘 통하는 이유다


-- 순환을 만든다

@AutoConfiguration(before = BetaAutoConfiguration.class)
public class AlphaAutoConfiguration { ... }

@AutoConfiguration(before = AlphaAutoConfiguration.class)
public class BetaAutoConfiguration { ... }

$ ./gradlew bootRun 2>&1 | head -5
Exception in thread "main" java.lang.IllegalStateException:
  AutoConfigure cycle detected between
  study.lib.AlphaAutoConfiguration and study.lib.BetaAutoConfiguration

--   조용하지 않다
--   기동이 멈춘다


-- 이름 문자열로도 적는다

@AutoConfiguration(afterName =
    "org.springframework.boot.autoconfigure.jdbc.DataSourceAutoConfiguration")
public class AlphaAutoConfiguration { ... }

// JDBC 스타터가 없어도
$ ./gradlew dependencies --configuration runtimeClasspath | grep -c starter-jdbc
0
$ ./gradlew bootRun 2>&1 | grep -c '\[구성\] alpha'
1

--   없는 이름은 그냥 무시된다
--   6.4절과 같은 이유로 안 터진다


-- 타입으로 적으면 다르다

@AutoConfiguration(after = DataSourceAutoConfiguration.class)

$ ./gradlew compileJava 2>&1 | head -2
> Task :compileJava FAILED
error: cannot find symbol  class DataSourceAutoConfiguration

--   컴파일에는 있어야 한다
--   남의 라이브러리면 이름 문자열이 안전하다


-- 순서 값도 있다

@AutoConfiguration
@AutoConfigureOrder(Ordered.HIGHEST_PRECEDENCE)
public class BetaAutoConfiguration { ... }

$ ./gradlew bootRun 2>&1 | grep '\[구성\]'
[구성] beta
[구성] alpha

// before 가 있으면 그게 이긴다
@AutoConfiguration(before = BetaAutoConfiguration.class)
public class AlphaAutoConfiguration { ... }

$ ./gradlew bootRun 2>&1 | grep '\[구성\]'
[구성] alpha
[구성] beta

--   앞뒤 지정이 순서 값보다 세다


-- 빈 생성 순서는 다르다

@AutoConfiguration
public class AlphaAutoConfiguration {
    public AlphaAutoConfiguration() { System.out.println("[구성] alpha"); }
    @Bean @Lazy Greeter alphaGreeter() { System.out.println("[빈] alpha"); return n -> "A"; }
}

$ ./gradlew bootRun 2>&1 | grep -E '\[구성\]|\[빈\]|Started'
[구성] alpha
[구성] beta
[빈] beta
INFO ... : Started BootApplication in 0.921 seconds

$ curl -s 'localhost:8080/greet?name=철수' > /dev/null
$ ./gradlew bootRun 2>&1 | grep '\[빈\] alpha'
[빈] alpha

--   구성은 기동 때 다 읽히고 빈은 필요할 때 만들어진다
--   두 순서가 다르다


-- 의존이 있으면 순서가 딸려 온다

@Bean Greeter alphaGreeter(Storage storage) {
    System.out.println("[빈] alpha, storage=" + storage.getClass().getSimpleName());
    return n -> "A";
}

$ ./gradlew bootRun 2>&1 | grep '\[빈\]'
[빈] storage
[빈] alpha, storage=MemoryStorage

--   구성 순서와 상관없이 필요한 게 먼저 만들어진다
--   ② 4장에서 보던 그것이다


-- 부트가 정해 둔 앞뒤를 센다

$ AC=$(find ~/.gradle/caches -name 'spring-boot-autoconfigure-3.3.2.jar' | head -1)
$ mkdir -p /tmp/ac && (cd /tmp/ac && unzip -oq "$AC" 'org/springframework/boot/autoconfigure/*')

$ for f in $(find /tmp/ac -name '*AutoConfiguration.class'); do
    javap -v "$f" 2>/dev/null | grep -q 'AUTO_CONFIGURE_AFTER\|after=' && echo "$f"
  done | wc -l
      63

$ javap -v /tmp/ac/org/springframework/boot/autoconfigure/orm/jpa/\
HibernateJpaAutoConfiguration.class | grep -A3 'AutoConfiguration' | head -4
  0: #52(#53=[c#54,c#55]): AUTO_CONFIGURATION
     DataSourceAutoConfiguration
     TransactionManagerCustomizationAutoConfiguration

--   161 중 63 이 앞뒤를 적어 뒀다
--   나머지는 순서를 안 따진다


-- 순서를 눈으로 본다

$ ./gradlew bootRun --args='--debug' 2>&1 \
    | sed -n '/^Positive matches:/,/^Negative matches:/p' \
    | grep ' matched:$' | grep -v '#' | head -6
   AopAutoConfiguration matched:
   ApplicationAvailabilityAutoConfiguration matched:
   DataSourceAutoConfiguration matched:
   DataSourceTransactionManagerAutoConfiguration matched:
   DispatcherServletAutoConfiguration matched:
   HibernateJpaAutoConfiguration matched:

--   보고서는 이름 순으로 정렬해 보여 준다
--   실제로 물은 순서가 아니다


-- 정리

$ printf '%-24s %s\n' \
  '순서'       '묻는 순서와 만드는 순서' \
  '기본'       '이름 순' \
  'before'     '앞으로' \
  'after'      '뒤로' \
  '내 구성'    '늘 먼저' \
  '순환'       '기동 멈춤' \
  '이름 문자열' '없으면 무시' \
  '앞뒤 vs 값' '앞뒤가 셈' \
  '부트 것'    '161 중 63'

순서                     묻는 순서와 만드는 순서
기본                     이름 순
before                   앞으로
after                    뒤로
내 구성                  늘 먼저
순환                     기동 멈춤
이름 문자열              없으면 무시
앞뒤 vs 값               앞뒤가 셈
부트 것                  161 중 63

